import React, { useCallback, useEffect, useRef, useState } from 'react';
import { FaImages, FaTimes, FaChevronLeft, FaChevronRight, FaExpand } from 'react-icons/fa';
import site from '../data/site';
import images from '../lib/images';
import * as s from './Gallery.module.css';

export default function Gallery() {
  const { gallery } = site;
  const shots = gallery.images;

  // null = closed. Otherwise the index of the open photo.
  const [open, setOpen] = useState(null);
  const dialogRef = useRef(null);
  const closeRef = useRef(null);
  const triggersRef = useRef([]);
  const lastOpened = useRef(null);

  const close = useCallback(() => setOpen(null), []);
  const next = useCallback(
    () => setOpen((i) => (i === null ? i : (i + 1) % shots.length)),
    [shots.length]
  );
  const prev = useCallback(
    () => setOpen((i) => (i === null ? i : (i - 1 + shots.length) % shots.length)),
    [shots.length]
  );

  // Keyboard control while the lightbox is open.
  useEffect(() => {
    if (open === null) return undefined;

    const onKey = (e) => {
      if (e.key === 'Escape') return close();
      if (e.key === 'ArrowRight') return next();
      if (e.key === 'ArrowLeft') return prev();
      if (e.key !== 'Tab') return undefined;

      // Keep Tab inside the dialog. Without this the focus ring walks off
      // behind the overlay onto a page the reader can no longer see.
      const focusable = dialogRef.current
        ? dialogRef.current.querySelectorAll('button, [href]')
        : null;
      if (!focusable || focusable.length === 0) return undefined;

      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      if (e.shiftKey && document.activeElement === first) {
        e.preventDefault();
        last.focus();
      } else if (!e.shiftKey && document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
      return undefined;
    };

    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [open, close, next, prev]);

  // Hold the page still behind the overlay, and pad for the scrollbar that
  // disappears with it so the layout underneath does not jump.
  useEffect(() => {
    if (open === null) return undefined;

    const { body } = document;
    const width = window.innerWidth - document.documentElement.clientWidth;
    const prevOverflow = body.style.overflow;
    const prevPad = body.style.paddingRight;
    body.style.overflow = 'hidden';
    if (width > 0) body.style.paddingRight = `${width}px`;

    return () => {
      body.style.overflow = prevOverflow;
      body.style.paddingRight = prevPad;
    };
  }, [open]);

  // Move focus into the dialog on open, and hand it back to the thumbnail that
  // opened it on close - otherwise keyboard users land back at the top.
  useEffect(() => {
    if (open !== null) {
      lastOpened.current = open;
      if (closeRef.current) closeRef.current.focus();
    } else if (lastOpened.current !== null) {
      const trigger = triggersRef.current[lastOpened.current];
      if (trigger) trigger.focus();
    }
  }, [open]);

  const current = open === null ? null : shots[open];

  return (
    <section className={s.section} id="work">
      <div className="container">
        <header className={s.head}>
          <span className={s.tag}>
            <FaImages aria-hidden="true" /> {gallery.tag}
          </span>
          <h2 className={s.title}>{gallery.title}</h2>
          <p className={s.sub}>{gallery.sub}</p>
        </header>

        <ul className={s.grid}>
          {shots.map((shot, i) => (
            <li key={shot.src}>
              <button
                type="button"
                className={s.tile}
                ref={(el) => {
                  triggersRef.current[i] = el;
                }}
                onClick={() => setOpen(i)}
                aria-label={`View photo ${i + 1} of ${shots.length}: ${shot.alt}`}
              >
                <img src={images[shot.src]} alt={shot.alt} loading="lazy" />
                <span className={s.hover} aria-hidden="true">
                  <FaExpand />
                </span>
              </button>
            </li>
          ))}
        </ul>
      </div>

      {current && (
        <div
          ref={dialogRef}
          className={s.overlay}
          role="dialog"
          aria-modal="true"
          aria-label={`Photo ${open + 1} of ${shots.length}`}
          onClick={(e) => {
            // Only a click on the backdrop itself closes, never one that
            // started on the photo or the controls.
            if (e.target === e.currentTarget) close();
          }}
        >
          <button ref={closeRef} type="button" className={s.close} onClick={close} aria-label="Close">
            <FaTimes />
          </button>

          <button
            type="button"
            className={`${s.arrow} ${s.left}`}
            onClick={prev}
            aria-label="Previous photo"
          >
            <FaChevronLeft />
          </button>

          <figure className={s.figure}>
            <img src={images[current.src]} alt={current.alt} />
            <figcaption className={s.counter}>
              {open + 1} / {shots.length}
            </figcaption>
          </figure>

          <button
            type="button"
            className={`${s.arrow} ${s.right}`}
            onClick={next}
            aria-label="Next photo"
          >
            <FaChevronRight />
          </button>
        </div>
      )}
    </section>
  );
}
