import React from 'react';
import {
  FaAward,
  FaHardHat,
  FaMapMarkerAlt,
  FaDollarSign,
  FaCheckCircle,
  FaArrowRight,
} from 'react-icons/fa';
import site from '../data/site';
import aboutImage from '../images/about.jpg';
import * as s from './About.module.css';

const ICONS = {
  hat: FaHardHat,
  pin: FaMapMarkerAlt,
  dollar: FaDollarSign,
};

export default function About() {
  const { about } = site;

  return (
    <section className={s.section} id="about">
      <div className={`container ${s.grid}`}>
        <div className={s.content}>
          <span className={s.tag}>
            <FaAward aria-hidden="true" /> {about.tag}
          </span>

          <h2 className={s.title}>
            {about.titleLead}
            <br />
            <em className={s.accent}>{about.titleAccent}</em>
          </h2>

          <p className={s.body}>{about.body}</p>

          <ul className={s.highlights}>
            {about.highlights.map((h) => {
              const Icon = ICONS[h.icon] || FaCheckCircle;
              return (
                <li key={h.text}>
                  <Icon aria-hidden="true" />
                  <span>{h.text}</span>
                </li>
              );
            })}
          </ul>

          <a className={s.cta} href="#contact">
            Get Your Free Quote <FaArrowRight aria-hidden="true" />
          </a>
        </div>

        <div className={s.imageCol}>
          <figure className={s.frame}>
            {/* A photo of their own finished work, not stock - it is the single
                most persuasive thing on the page. */}
            <img src={aboutImage} alt={`Siding work completed by ${site.businessName}`} loading="lazy" />
            <figcaption className={s.caption}>
              <FaCheckCircle aria-hidden="true" /> {about.imageCaption}
            </figcaption>
          </figure>
        </div>
      </div>
    </section>
  );
}
