import React, { useEffect, useState } from 'react';
import { FaBars, FaTimes, FaPhoneAlt } from 'react-icons/fa';
import site from '../data/site';
import TopBar from './TopBar';
import logo from '../images/logo.png';
import * as s from './Header.module.css';

const NAV = [
  { label: 'Home', href: '#top' },
  { label: 'Services', href: '#services' },
  { label: 'About', href: '#about' },
  { label: 'Our Work', href: '#work' },
  { label: 'Contact', href: '#contact' },
];

/**
 * Floats over the hero video as a white pill, then pins to the top as a solid
 * bar once the hero is behind you. The logo spells the business name itself,
 * so no wordmark is set beside it.
 */
export default function Header() {
  const [pinned, setPinned] = useState(false);
  const [open, setOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setPinned(window.scrollY > 90);
    onScroll();
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  // A menu left open behind a resize into desktop would trap the layout.
  useEffect(() => {
    const onResize = () => window.innerWidth > 860 && setOpen(false);
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  }, []);

  return (
    <header className={`${s.header} ${pinned ? s.pinned : ''}`}>
      {!pinned && <TopBar />}

      <div className="container">
        <div className={s.pill}>
          <a className={s.logoLink} href="#top" aria-label={`${site.businessName} home`}>
            <img className={s.logo} src={logo} alt={`${site.businessName} logo`} />
          </a>

          <nav className={s.nav} aria-label="Main">
            <ul className={s.navList}>
              {NAV.map((item) => (
                <li key={item.label}>
                  <a className={s.navLink} href={item.href}>
                    {item.label}
                  </a>
                </li>
              ))}
            </ul>
          </nav>

          <div className={s.actions}>
            <a className={s.call} href={site.phoneHref}>
              <FaPhoneAlt aria-hidden="true" />
              <span>{site.phone}</span>
            </a>
            <a className={s.cta} href="#contact">
              Free Quote
            </a>
            <button
              className={s.burger}
              type="button"
              onClick={() => setOpen((v) => !v)}
              aria-expanded={open}
              aria-controls="mobile-menu"
              aria-label={open ? 'Close menu' : 'Open menu'}
            >
              {open ? <FaTimes /> : <FaBars />}
            </button>
          </div>
        </div>
      </div>

      <div id="mobile-menu" className={`${s.mobile} ${open ? s.mobileOpen : ''}`} hidden={!open}>
        <ul>
          {NAV.map((item) => (
            <li key={item.label}>
              <a href={item.href} onClick={() => setOpen(false)}>
                {item.label}
              </a>
            </li>
          ))}
        </ul>
        <a className={s.mobileCall} href={site.phoneHref}>
          <FaPhoneAlt aria-hidden="true" /> Call {site.phone}
        </a>
      </div>
    </header>
  );
}
