import React, { useEffect, useRef } from 'react';
import { FaCheckCircle, FaPhoneAlt, FaArrowRight, FaHardHat, FaMapMarkerAlt } from 'react-icons/fa';
import site from '../data/site';
import poster from '../images/hero-poster.jpg';
import * as s from './Hero.module.css';

/**
 * Hero with the saw clip running behind it.
 *
 * The video is decoration, not content: it is muted, loops, carries no audio
 * track anyone needs, and every word stays legible on the poster frame alone.
 * If the file is missing or the browser blocks autoplay, the poster image
 * holds the section and nothing below it shifts.
 */
export default function Hero() {
  const videoRef = useRef(null);

  useEffect(() => {
    const el = videoRef.current;
    if (!el) return;

    // Someone who asked their OS for less motion should not be handed a
    // looping clip. They get the poster frame instead.
    const reduced = window.matchMedia('(prefers-reduced-motion: reduce)');
    const apply = () => {
      if (reduced.matches) {
        el.pause();
        el.removeAttribute('autoplay');
      } else {
        const p = el.play();
        // Autoplay rejection is normal on some mobile browsers - the poster
        // is already showing, so swallow it rather than logging noise.
        if (p && typeof p.catch === 'function') p.catch(() => {});
      }
    };

    apply();
    reduced.addEventListener('change', apply);
    return () => reduced.removeEventListener('change', apply);
  }, []);

  return (
    <section className={s.hero} id="top">
      <div className={s.media} aria-hidden="true">
        <video
          ref={videoRef}
          className={s.video}
          poster={poster}
          autoPlay
          muted
          loop
          playsInline
          preload="metadata"
        >
          {site.hero.sources.map((source) => (
            <source key={source.src} src={source.src} type={source.type} />
          ))}
        </video>
        <div className={s.scrim} />
        <div className={s.vignette} />
      </div>

      <div className={`container ${s.inner}`}>
        <span className={s.eyebrow}>
          <FaCheckCircle aria-hidden="true" /> {site.hero.eyebrow}
        </span>

        <h1 className={s.title}>
          {site.hero.titleLead} <em className={s.accent}>{site.hero.titleAccent}</em>
        </h1>

        <p className={s.body}>{site.hero.body}</p>

        <div className={s.actions}>
          <a className={s.primary} href="#contact">
            Get Your Free Quote <FaArrowRight aria-hidden="true" />
          </a>
          <a className={s.secondary} href={site.phoneHref}>
            <FaPhoneAlt aria-hidden="true" /> {site.phone}
          </a>
        </div>

        <ul className={s.trust}>
          <li>
            <FaHardHat aria-hidden="true" />
           {['Framing', 'Remodels', 'Decks', 'Siding', 'Windows', 'Doors', 'Fences'].join(' • ')}
          </li>
          <li>
            <FaMapMarkerAlt aria-hidden="true" />
            Serving {site.serviceArea}
          </li>
        </ul>
      </div>
    </section>
  );
}
